GetShow.query:
query GetShow($showId: String, $eventId: String) {
  show(id: $showId, eventId: $eventId) {
    id
    ageRequirements
    allDayEvent
    arenaTheater { name boxOfficeHours { description time } location { address } }
    bookingFlowGroupReservation
    darkDates
    descriptions { appCard overview learnMore long secondary short tagline }
    images {
      tile { url metadata { description } }
      overview { url metadata { description height width } }
      detailPageHeroGallery { type reference { url } caption }
    }
    name
    productCategory
    property {
      id name
      location { address latitude longitude }
    }
    seasons { id displayName seatMap { seatingType } termsConditionsFormatted }
    lastAdmissionTime
    guestReminderMessage { heading description }
  }
}

GetShowEventsView.query:
query GetShowEventsView($endDate: String, $limit: Int!, $offset: Int!, $propertyId: String!, $showId: String!, $startDate: String!) {
  showBooking {
    eventsViewForShow(queryParams: {
      endDate: $endDate, limit: $limit, offset: $offset,
      propertyId: $propertyId, showId: $showId, startDate: $startDate
    }) {
      events {
        eventDate
        eventTime
        eventId
        eventCode
        seasonId
        offerAvailable
        lowestPrice
      }
      lastUpdated
    }
  }
}

GetCalendarView.query:
query GetCalendarView($showId: String, $propertyId: String, $seasonId: String, $programId: String, $startDate: String!, $endDate: String!, $redemptionCode: String) {
  showBooking {
    calendarView(queryParams: {
      showId: $showId, propertyId: $propertyId, seasonId: $seasonId,
      programId: $programId, startDate: $startDate, endDate: $endDate,
      redemptionCode: $redemptionCode
    }) {
      date
      available
      offerAvailable
      lowestPrice
    }
  }
}

GetShowEvent.query:
query GetShowEvent($showEventId: String!) {
  getShowEvent(id: $showEventId) {
    id
    eventDate
    eventTime
    seasonId
  }
}

GetSeatsAvailability.query:
query GetSeatsAvailability($showEventId: String!, $programId: String, $numTicket: Int, $sections: String, $priceCodes: String, $redemptionCode: String, $numAdaTickets: Int, $numCompanionTickets: Int, $offerSeatsOnly: Boolean, $propertyId: String) {
  showBooking {
    seatsAvailability(queryParams: {
      showEventId: $showEventId, programId: $programId,
      numTickets: $numTicket, sections: $sections,
      priceCodes: $priceCodes, redemptionCode: $redemptionCode,
      numAdaTickets: $numAdaTickets, numCompanionTickets: $numCompanionTickets,
      offerSeatsOnly: $offerSeatsOnly, propertyId: $propertyId
    }) {
      limitedAvailability
      comp
      hdePackage
      seats {
        count
        startingPrice
        name
        seatRows {
          name
          seats {
            firstSeat
            lastSeat
            numSeats
            seatIncrement
            priceCode
            basePrice
            discountedPrice
            priceLevel
            holdClass
            ada
            adaCompanion
            vip
          }
        }
      }
      prices {
        code
        description
        price {
          basePrice
          discountedPrice
          comp
          hdePackage
          discounted
          basePriceWithServiceFee
          discountedPriceWithServiceFee
          serviceFee
        }
        minTickets
        maxTickets
        totalAvailableSeats
        ticketTypeCode
        ticketTypeDescription
        offerApplicable
      }
      seatRowsSortedByPrice {
        name
        sectionName
        startingPrice
        numSeats
      }
    }
  }
}

GetOffers.query:
query GetOffers($propertyId: String, $showId: String) {
  showBooking {
    offers(queryParams: { propertyId: $propertyId, showId: $showId }) {
      programDetails {
        id
        active
        bookStartDate
        bookEndDate
        bookableOnline
        descriptions { short subtitle }
        minTickets
        maxTickets
        ticketMultiple
        name
        propertyId
        termsConditions
        type
        myvegas
        events
        startingPrice
        isComp
      }
    }
  }
}
